    [-1.9931055474e-01f32, 3.2909704572e-02f32, -2.2572343852e-01f32, -6.0585036935e-01f32, 7.4679516796e-01f32, -4.0582494516e-01f32, 3.3035574587e-01f32, -2.4799395996e-01f32, -5.2656947574e-01f32, 6.8591546822e-02f32, 5.8628097386e-01f32, 1.3985348941e-01f32, 2.0323723283e-01f32, 2.9374496024e-01f32, 3.7819195000e-01f32, 4.5831368078e-01f32, -3.4220078424e-01f32, -5.4812284040e-01f32, -4.3007548319e-01f32, 5.0549992727e-01f32, 6.4946108441e-01f32, -5.5597655786e-01f32, 2.2548007044e-01f32, 7.4152547369e-01f32, -2.8493467819e-01f32, 8.8748924185e-02f32, 6.4982661425e-01f32, -6.0075404878e-01f32, 1.2775365562e-01f32, -4.2232281651e-01f32, 2.8492386311e-01f32, 3.6099040487e-01f32];

const B2: f32 =
    3.0718433722e-01f32;

#[derive(Deserialize)]
struct InferenceRequest {
    features: Vec<f32>,
}

#[derive(Serialize)]
struct InferenceResponse {
    prediction: i32,
    inference_time_ns: u128,
}

fn predict_mlp(input: &[f32]) -> i32 {

    let mut hidden = [0.0f32; N_HIDDEN];

    let mut h = 0usize;

    while h < N_HIDDEN {

        let mut sum = B1[h];
        let mut i = 0usize;

        while i < N_INPUT {

            let x =
                (input[i] - MEAN[i]) /
                SCALE[i];

            sum +=
                x * W1[i * N_HIDDEN + h];

            i += 1;
        }

        hidden[h] =
            if sum > 0.0f32 {
                sum
            } else {
                0.0f32
            };

        h += 1;
    }

    let mut out = B2;

    h = 0;

    while h < N_HIDDEN {
        out += hidden[h] * W2[h];
        h += 1;
    }

    let probability =
        1.0f32 /
        (1.0f32 + (-out).exp());

    if probability >= 0.5f32 {
        1
    } else {
        0
    }
}

async fn infer(
    Json(payload): Json<InferenceRequest>
) -> Result<Json<InferenceResponse>, (axum::http::StatusCode, String)> {

    if payload.features.len() != N_INPUT {
        return Err((
            axum::http::StatusCode::BAD_REQUEST,
            format!(
                "Expected {} features, received {}",
                N_INPUT,
                payload.features.len()
            )
        ));
    }

    let start = Instant::now();

    let prediction =
        predict_mlp(&payload.features);

    Ok(Json(InferenceResponse {
        prediction,
        inference_time_ns: start.elapsed().as_nanos(),
    }))
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {

    println!("Starting Native Docker MLP Server");

    let app =
        Router::new().route("/infer", post(infer));

    let addr =
        SocketAddr::from(([0,0,0,0], 8085));

    println!(
        "Docker MLP server listening on http://{}",
        addr
    );

    let listener =
        tokio::net::TcpListener::bind(addr).await?;

    axum::serve(listener, app).await?;

    Ok(())
}
